let () =
  match
    Vhs.tape
      ~settings:
        [
          Shell Bash;
          Font_size 18;
          Width 1000;
          Height 560;
          Theme "Builtin Dark";
          Padding 20;
          Typing_speed (Ms 20);
        ]
      ~outputs:[ "examples/matrix/matrix.gif" ]
      [
        Vhs.raw
          "# Generated by tape.ml: a themed event history with one bounded \
           live region.";
        Vhs.raw {|Require "dune"|};
        Vhs.type' "dune exec examples/matrix/main.exe\n";
        Vhs.wait (Screen "There is no spoon.");
        Vhs.sleep (Ms 2000);
      ]
  with
  | Ok t -> print_string (Vhs.to_string t)
  | Error e ->
      prerr_endline e;
      exit 1
